"""Path model of C(g,k) generated by V, modulo p, built from the cell data of cells.py.

For a base object X the path space P_X(n) = Hom(-, X (x) V^n) has basis the edge paths
X = Z0 -e1-> Z1 -e2-> ... -en-> Zn; morphisms between tensor powers of V act by sparse
matrices assembled from the cells (braiding, cup, cap, split, merge).  All matrices are
block diagonal for the endpoint Zn, which is not changed by any operator.
"""
import numpy as np
import scipy.sparse as sp


class Paths:
    def __init__(self, cells, X, n):
        self.X, self.n = X, n
        alc = cells["alcove"]
        nb = {}
        for (A, B), m in cells["edges"].items():
            nb.setdefault(A, []).append((B, m))
        self.nb = nb
        lst = [((X,), ())]               # (vertices, edges)
        for _ in range(n):
            lst = [(vs + (B,), es + (e,)) for vs, es in lst for B, m in nb[vs[-1]] for e in range(m)]
        lst.sort(key=lambda t: (alc.index(t[0][-1]), t))
        self.paths = lst
        self.index = {t: i for i, t in enumerate(lst)}
        self.end = np.array([alc.index(t[0][-1]) for t in lst])
        self.blk = {}
        for T in alc:
            idx = np.nonzero(self.end == alc.index(T))[0]
            if len(idx):
                self.blk[T] = (int(idx[0]), int(idx[-1]) + 1)

    def __len__(self):
        return len(self.paths)


class Model:
    def __init__(self, cells):
        self.c = cells
        self.p = cells["p"]
        self.alc = cells["alcove"]
        self.cidx = {key: {t: i for i, t in enumerate(v)} for key, v in cells["paths"].items()}
        self._ps = {}
        self._ops = {}

    def P(self, X, n):
        if (X, n) not in self._ps:
            self._ps[(X, n)] = Paths(self.c, X, n)
        return self._ps[(X, n)]

    def _sparse(self, rows, cols, vals, shape):
        M = sp.csr_matrix((np.array(vals, dtype=np.int64) % self.p, (rows, cols)), shape=shape, dtype=np.int64)
        M.sum_duplicates()
        M.data %= self.p
        M.eliminate_zeros()
        return M

    def op(self, X, n, kind, i):
        """Sparse matrix of a generator acting on P_X(n).
        kind 'sigma' (steps i, i+1; 1 <= i < n), 'cup' (insert two steps after vertex i,
        0 <= i <= n), 'cap' (contract steps i+1, i+2), 'split' (step i -> two steps),
        'merge' (steps i, i+1 -> one step)."""
        key = (X, n, kind, i)
        if key in self._ops:
            return self._ops[key]
        c, p = self.c, self.p
        src = self.P(X, n)
        rows, cols, vals = [], [], []
        if kind == "sigma":
            dst = src
            for a, (vs, es) in enumerate(src.paths):
                A, C = vs[i - 1], vs[i + 1]
                lst = c["paths"][(A, C)]
                j = self.cidx[(A, C)][(vs[i], es[i - 1], es[i])]
                col = c["sigma"][(A, C)][:, j]
                for t, (B, e1, e2) in enumerate(lst):
                    if col[t]:
                        nv = vs[:i] + (B,) + vs[i + 1:]
                        ne = es[:i - 1] + (e1, e2) + es[i + 1:]
                        rows.append(dst.index[(nv, ne)]); cols.append(a); vals.append(int(col[t]))
        elif kind == "cup":
            dst = self.P(X, n + 2)
            for a, (vs, es) in enumerate(src.paths):
                A = vs[i]
                lst = c["paths"][(A, A)]
                col = c["cup"][A]
                for t, (B, e1, e2) in enumerate(lst):
                    if col[t]:
                        nv = vs[:i + 1] + (B, A) + vs[i + 1:]
                        ne = es[:i] + (e1, e2) + es[i:]
                        rows.append(dst.index[(nv, ne)]); cols.append(a); vals.append(int(col[t]))
        elif kind == "cap":
            dst = self.P(X, n - 2)
            for a, (vs, es) in enumerate(src.paths):
                A, C = vs[i], vs[i + 2]
                if A != C:
                    continue
                j = self.cidx[(A, A)][(vs[i + 1], es[i], es[i + 1])]
                v = int(c["cap"][A][j])
                if v:
                    nv = vs[:i + 1] + vs[i + 3:]
                    ne = es[:i] + es[i + 2:]
                    rows.append(dst.index[(nv, ne)]); cols.append(a); vals.append(v)
        elif kind == "split":
            dst = self.P(X, n + 1)
            for a, (vs, es) in enumerate(src.paths):
                A, C = vs[i - 1], vs[i]
                lst = c["paths"][(A, C)]
                col = c["split"][(A, C)][:, es[i - 1]]
                for t, (B, e1, e2) in enumerate(lst):
                    if col[t]:
                        nv = vs[:i] + (B,) + vs[i:]
                        ne = es[:i - 1] + (e1, e2) + es[i:]
                        rows.append(dst.index[(nv, ne)]); cols.append(a); vals.append(int(col[t]))
        elif kind == "merge":
            dst = self.P(X, n - 1)
            for a, (vs, es) in enumerate(src.paths):
                A, C = vs[i - 1], vs[i + 1]
                if (A, C) not in c["merge"]:
                    continue
                j = self.cidx[(A, C)][(vs[i], es[i - 1], es[i])]
                col = c["merge"][(A, C)][:, j]
                for e in range(len(col)):
                    if col[e]:
                        nv = vs[:i] + vs[i + 1:]
                        ne = es[:i - 1] + (e,) + es[i + 1:]
                        rows.append(dst.index[(nv, ne)]); cols.append(a); vals.append(int(col[e]))
        else:
            raise ValueError(kind)
        M = self._sparse(rows, cols, vals, (len(dst), len(src)))
        self._ops[key] = M
        return M

    def opT(self, X, n, kind, i, T):
        """The generator restricted to the endpoint-T blocks (None if a block is empty)."""
        key = (X, n, kind, i, T)
        if key not in self._ops:
            M = self.op(X, n, kind, i)
            n2 = n + {"sigma": 0, "cup": 2, "cap": -2, "split": 1, "merge": -1}[kind]
            b1 = self.P(X, n).blk.get(T)
            b2 = self.P(X, n2).blk.get(T)
            self._ops[key] = None if (b1 is None or b2 is None) else M[b2[0]:b2[1], b1[0]:b1[1]].tocsr()
        return self._ops[key]

    def wordT(self, X, n, T, word, x):
        """Apply a word to columns x living in the T-block of P_X(n)."""
        for kind, i in word:
            M = self.opT(X, n, kind, i, T)
            n += {"sigma": 0, "cup": 2, "cap": -2, "split": 1, "merge": -1}[kind]
            if M is None:
                b = self.P(X, n).blk.get(T)
                x = np.zeros((0 if b is None else b[1] - b[0], x.shape[1]), dtype=np.int64)
            else:
                x = self.apply(M, x)
        return x, n

    def apply(self, M, x):
        """M (sparse) applied to dense columns x mod p."""
        p = self.p
        hi = (M @ (x >> 15)) % p
        lo = (M @ (x & 0x7FFF)) % p
        return ((hi << 15) + lo) % p

    def word(self, X, n, word, x):
        """Apply a word [(kind, i), ...] (rightmost first in composition = first in list)."""
        for kind, i in word:
            M = self.op(X, n, kind, i)
            x = self.apply(M, x)
            n += {"sigma": 0, "cup": 2, "cap": -2, "split": 1, "merge": -1}[kind]
        return x, n
